{
  "turn": "initial",
  "case": {
    "caseId": "DEV-02",
    "request": {
      "id": "U1",
      "text": "동아리 회비 앱의 회비 내역 화면에서 버튼 문구만 “추가”에서 “입금 기록”으로 바꿔줘. 모바일의 같은 화면에도 적용해. 버튼 위치·색·클릭 후 동작·저장 데이터는 그대로 두고 다른 화면은 건드리지 마."
    },
    "context": [
      {
        "id": "C1",
        "text": "이 화면의 해당 버튼은 하나이고, 현재 누르면 기존 입금 기록 입력창이 열립니다. 이번 요청은 이미 있는 앱의 문구 수정입니다."
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "text": "회원 초대와 권한 구조는 이번 변경에 포함하지 않는다.",
        "status": "confirmed",
        "locked": true
      }
    ],
    "materials": []
  }
}

