        "text": "- <span aria-live=\"polite\">{saveState === \"saved\" ? \"저장 완료\" : statusLabel}</span>\n+ <span aria-live=\"polite\">{saveState === \"saved\" ? \"저장됨\" : statusLabel}</span>"
      },
